def score(secret, guess):
    gap = abs(secret - guess)
    for limit, points in [(0, 10), (2, 5), (10, 1)]:
        if gap <= limit:
            return points
    return 0

def verdict(secret, guess):
    points = score(secret, guess)
    too_high = guess > secret
    return points, too_high
